use clap::{Parser, ValueEnum};
use colored::Colorize;
use std::fs::File;
use std::io::{self, Read, BufReader};
use std::path::PathBuf;

#[derive(Parser, Debug)]
#[command(about = "Futuristic take on hexdump, made in Rust.")]
#[command(version = "hx 0.7.0")]
struct Args {
    /// Pass file path as an argument, or input data may be passed via stdin
    #[arg(value_name = "INPUTFILE")]
    inputfile: Option<PathBuf>,

    /// Set column length
    #[arg(short, long, value_name = "columns")]
    cols: Option<usize>,

    /// Set <len> bytes to read
    #[arg(short, long, value_name = "len")]
    len: Option<usize>,

    /// Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b)
    #[arg(short, long, value_name = "format")]
    format: Option<char>,

    /// Set color tint terminal output. 0 to disable, 1 to enable
    #[arg(short, long, value_name = "color")]
    color: Option<u8>,

    /// Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)
    #[arg(short, long, value_name = "array_format")]
    array: Option<char>,

    /// Set function wave length
    #[arg(short, long, value_name = "func_length")]
    func: Option<usize>,

    /// Set function wave output decimal places
    #[arg(short, long, value_name = "func_places")]
    places: Option<usize>,

    /// Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable
    #[arg(short, long, value_name = "prefix")]
    prefix: Option<u8>,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    // Determine if colors should be used
    let use_color = if let Some(c) = args.color {
        c == 1
    } else {
        // Check NO_COLOR environment variable
        std::env::var("NO_COLOR").is_err()
    };

    // Default values
    let columns = args.cols.unwrap_or(10);
    let max_len = args.len;
    let format_char = args.format.unwrap_or('x');
    let prefix_enabled = args.prefix.unwrap_or(1) == 1;

    // Read input
    let mut input = Vec::new();
    if let Some(path) = &args.inputfile {
        let mut file = File::open(path)
            .map_err(|e| format!("error: {} (os error {})", e, e.raw_os_error().unwrap_or(0)))?;
        file.read_to_end(&mut input)?;
    } else {
        io::stdin().read_to_end(&mut input)?;
    }

    // Limit by len if specified
    if let Some(max) = max_len {
        input.truncate(max);
    }

    // Process based on mode
    if let Some(array_format) = args.array {
        print_array_format(&input, array_format, use_color)?;
    } else {
        print_hex_dump(&input, columns, format_char, use_color, prefix_enabled);
        println!("   bytes: {}", input.len());
    }

    Ok(())
}

fn print_hex_dump(input: &[u8], columns: usize, format_char: char, use_color: bool, prefix_enabled: bool) {
    let mut offset = 0;
    while offset < input.len() {
        let end = std::cmp::min(offset + columns, input.len());
        let chunk = &input[offset..end];

        // Print offset
        print!("0x{:06x}:", offset);

        // Print hex values
        print!(" ");
        for (i, byte) in chunk.iter().enumerate() {
            if i > 0 {
                print!(" ");
            }
            print_byte(*byte, format_char, use_color, prefix_enabled);
        }

        // Padding for incomplete lines
        if chunk.len() < columns {
            for _ in chunk.len()..columns {
                print!("                    "); // Adjust width based on format
            }
        }

        // Print ASCII representation
        print!(" ");
        for byte in chunk {
            let ch = if *byte >= 32 && *byte <= 126 {
                *byte as char
            } else {
                '.'
            };
            if use_color {
                print!("{}", ch.to_string().cyan());
            } else {
                print!("{}", ch);
            }
        }

        println!();
        offset = end;
    }
}

fn print_byte(byte: u8, format_char: char, use_color: bool, prefix_enabled: bool) {
    let formatted = match format_char {
        'x' => {
            if prefix_enabled {
                format!("0x{:02x}", byte)
            } else {
                format!("{:02x}", byte)
            }
        }
        'X' => {
            if prefix_enabled {
                format!("0x{:02X}", byte)
            } else {
                format!("{:02X}", byte)
            }
        }
        'o' => {
            if prefix_enabled {
                format!("0o{:04o}", byte)
            } else {
                format!("{:04o}", byte)
            }
        }
        'b' => {
            if prefix_enabled {
                format!("0b{:08b}", byte)
            } else {
                format!("{:08b}", byte)
            }
        }
        _ => format!("0x{:02x}", byte),
    };

    if use_color {
        print!("{}", formatted.yellow());
    } else {
        print!("{}", formatted);
    }
}

fn print_array_format(input: &[u8], format: char, _use_color: bool) -> Result<(), Box<dyn std::error::Error>> {
    match format {
        'r' => print_rust_array(input),
        'c' => print_c_array(input),
        'g' => print_go_array(input),
        'p' => print_python_array(input),
        'k' => print_kotlin_array(input),
        'j' => print_java_array(input),
        's' => print_swift_array(input),
        'f' => print_fsharp_array(input),
        _ => Err(format!("Unknown array format: {}", format).into()),
    }

    Ok(())
}

fn print_rust_array(input: &[u8]) {
    println!("let ARRAY: [u8; {}] = [", input.len());
    for (i, byte) in input.iter().enumerate() {
        if i > 0 && i % 10 == 0 {
            println!();
            print!("    ");
        } else if i > 0 {
            print!(" ");
        } else {
            print!("    ");
        }
        print!("0x{:02x},", byte);
    }
    println!();
    println!("];");
}

fn print_c_array(input: &[u8]) {
    println!("unsigned char ARRAY[{}] = {{", input.len());
    for (i, byte) in input.iter().enumerate() {
        if i > 0 && i % 10 == 0 {
            println!();
            print!("    ");
        } else if i > 0 {
            print!(" ");
        } else {
            print!("    ");
        }
        print!("0x{:02x},", byte);
    }
    println!();
    println!("}};");
}

fn print_go_array(input: &[u8]) {
    println!("a := [{}]byte{{", input.len());
    for (i, byte) in input.iter().enumerate() {
        if i > 0 && i % 10 == 0 {
            println!();
            print!("    ");
        } else if i > 0 {
            print!(" ");
        } else {
            print!("    ");
        }
        print!("0x{:02x},", byte);
    }
    println!(" ");
    println!("}},");
}

fn print_python_array(input: &[u8]) {
    println!("a = [");
    for (i, byte) in input.iter().enumerate() {
        if i > 0 && i % 10 == 0 {
            println!();
            print!("    ");
        } else if i > 0 {
            print!(" ");
        } else {
            print!("    ");
        }
        print!("0x{:02x},", byte);
    }
    println!();
    println!("]");
}

fn print_kotlin_array(input: &[u8]) {
    println!("val a = byteArrayOf(");
    for (i, byte) in input.iter().enumerate() {
        if i > 0 && i % 10 == 0 {
            println!();
            print!("    ");
        } else if i > 0 {
            print!(" ");
        } else {
            print!("    ");
        }
        print!("0x{:02x}", byte);
        if i < input.len() - 1 {
            print!(",");
        }
    }
    println!();
    println!(")");
}

fn print_java_array(input: &[u8]) {
    println!("byte[] a = new byte[]{{");
    for (i, byte) in input.iter().enumerate() {
        if i > 0 && i % 10 == 0 {
            println!();
            print!("    ");
        } else if i > 0 {
            print!(" ");
        } else {
            print!("    ");
        }
        print!("0x{:02x},", byte);
    }
    println!();
    println!("}};");
}

fn print_swift_array(input: &[u8]) {
    println!("let a: [UInt8] = [");
    for (i, byte) in input.iter().enumerate() {
        if i > 0 && i % 10 == 0 {
            println!();
            print!("    ");
        } else if i > 0 {
            print!(" ");
        } else {
            print!("    ");
        }
        print!("0x{:02x},", byte);
    }
    println!();
    println!("]");
}

fn print_fsharp_array(input: &[u8]) {
    println!("let a = [|");
    for (i, byte) in input.iter().enumerate() {
        if i > 0 {
            print!("; ");
        } else {
            print!("    ");
        }
        print!("0x{:02x}uy", byte);
    }
    println!();
    println!("|]");
}
