    }
}

fn parse_args() -> Result<Args, String> {
    let args: Vec<String> = env::args().collect();
    let mut parsed = Args::new();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => {
                parsed.help = true;
            }
            "-V" | "--version" => {
                parsed.version = true;
            }
            "-c" | "--cols" => {
                i += 1;
