                    return Err("Missing value for --cols".to_string());
                }
                parsed.cols = Some(args[i].parse().map_err(|_| "Invalid cols value".to_string())?);
            }
            "-l" | "--len" => {
                i += 1;
                if i >= args.len() {
                    return Err("Missing value for --len".to_string());
                }
                parsed.len = Some(args[i].parse().map_err(|_| "Invalid len value".to_string())?);
            }
            "-f" | "--format" => {
                i += 1;
                if i >= args.len() {
                    return Err("Missing value for --format".to_string());
                }
                let chars: Vec<char> = args[i].chars().collect();
                if chars.len() != 1 {
                    return Err("Format must be a single character".to_string());
                }
                parsed.format = Some(chars[0]);
            }
            "-t" | "--color" => {
                i += 1;
                if i >= args.len() {
                    return Err("Missing value for --color".to_string());
                }
                parsed.color = Some(args[i].parse().map_err(|_| "Invalid color value".to_string())?);
            }
            "-a" | "--array" => {
                i += 1;
                if i >= args.len() {
                    return Err("Missing value for --array".to_string());
                }
                let chars: Vec<char> = args[i].chars().collect();
                if chars.len() != 1 {
                    return Err("Array format must be a single character".to_string());
                }
                parsed.array = Some(chars[0]);
            }
            "-u" | "--func" => {
                i += 1;
                if i >= args.len() {
                    return Err("Missing value for --func".to_string());
                }
                parsed.func = Some(args[i].parse().map_err(|_| "Invalid func value".to_string())?);
            }
            "-p" | "--places" => {
                i += 1;
                if i >= args.len() {
                    return Err("Missing value for --places".to_string());
                }
                parsed.places = Some(args[i].parse().map_err(|_| "Invalid places value".to_string())?);
            }
            "-r" | "--prefix" => {
                i += 1;
