                    return Err("Missing value for --prefix".to_string());
                }
                parsed.prefix = Some(args[i].parse().map_err(|_| "Invalid prefix value".to_string())?);
            }
            _ => {
                if arg.starts_with('-') {
                    return Err(format!("Unknown flag: {}", arg));
                }
                parsed.inputfile = Some(PathBuf::from(arg));
            }
        }

        i += 1;
    }

    Ok(parsed)
