fn print_hex_dump(input: &[u8], columns: usize, format_char: char, use_color: bool, prefix_enabled: bool) {
    let mut offset = 0;
    while offset < input.len() {
        let end = std::cmp::min(offset + columns, input.len());
        let chunk = &input[offset..end];

        // Print offset
        print!("0x{:06x}:", offset);

        // Print hex values
        print!(" ");
        for (i, byte) in chunk.iter().enumerate() {
            if i > 0 {
                print!(" ");
            }
            print_byte(*byte, format_char, use_color, prefix_enabled);
        }

        // Padding for incomplete lines
        if chunk.len() < columns {
            let width = get_byte_width(format_char);
            for _ in chunk.len()..columns {
                for _ in 0..width {
                    print!(" ");
                }
            }
        }

        // Print ASCII representation
        print!(" ");
        for byte in chunk {
            let ch = if *byte >= 32 && *byte <= 126 {
                *byte as char
            } else {
                '.'
            };
            if use_color {
                print!("{}", colorize_cyan(&ch.to_string()));
            } else {
                print!("{}", ch);
            }
        }

        println!();
        offset = end;
    }
}

fn get_byte_width(format_char: char) -> usize {
    match format_char {
        'x' => 4,  // "0x00" or "00"
        'X' => 4,
        'o' => 6,  // "0o0000" or "0000"
        'b' => 10, // "0b00000000" or "00000000"
        _ => 4,
    }
}

fn print_byte(byte: u8, format_char: char, use_color: bool, prefix_enabled: bool) {
    let formatted = match format_char {
        'x' => {
            if prefix_enabled {
                format!("0x{:02x}", byte)
            } else {
                format!("{:02x}", byte)
            }
        }
        'X' => {
            if prefix_enabled {
                format!("0x{:02X}", byte)
            } else {
                format!("{:02X}", byte)
            }
        }
        'o' => {
            if prefix_enabled {
                format!("0o{:04o}", byte)
            } else {
                format!("{:04o}", byte)
            }
        }
        'b' => {
            if prefix_enabled {
                format!("0b{:08b}", byte)
            } else {
                format!("{:08b}", byte)
            }
        }
        _ => format!("0x{:02x}", byte),
    };

    if use_color {
        print!("{}", colorize_yellow(&formatted));
    } else {
        print!("{}", formatted);
    }
}

fn print_array_format(input: &[u8], format: char, _use_color: bool) -> Result<(), Box<dyn std::error::Error>> {
