fn write_byte<W: Write>(w: &mut W, byte: u8, format_char: char, use_color: bool, prefix_enabled: bool) -> io::Result<()> {
    let formatted = match format_char {
        'x' => {
            if prefix_enabled {
                format!("0x{:02x}", byte)
            } else {
                format!("{:02x}", byte)
            }
        }
        'X' => {
            if prefix_enabled {
                format!("0x{:02X}", byte)
            } else {
                format!("{:02X}", byte)
            }
        }
        'o' => {
            if prefix_enabled {
                format!("0o{:04o}", byte)
            } else {
                format!("{:04o}", byte)
            }
        }
        'b' => {
            if prefix_enabled {
                format!("0b{:08b}", byte)
            } else {
                format!("{:08b}", byte)
            }
        }
        _ => format!("0x{:02x}", byte),
    };

    if use_color {
        write!(w, "{}", colorize_yellow(&formatted))
    } else {
        write!(w, "{}", formatted)
    }
