fn print_hex_dump(input: &[u8], columns: usize, format_char: char, use_color: bool, prefix_enabled: bool) -> io::Result<()> {
    let mut stdout = io::stdout().lock();
    let mut offset = 0;
    while offset < input.len() {
        let end = std::cmp::min(offset + columns, input.len());
        let chunk = &input[offset..end];

        // Print offset
        write!(stdout, "0x{:06x}:", offset)?;

        // Print hex values
        write!(stdout, " ")?;
        for (i, byte) in chunk.iter().enumerate() {
            if i > 0 {
                write!(stdout, " ")?;
            }
            write_byte(&mut stdout, *byte, format_char, use_color, prefix_enabled)?;
        }

        // Padding for incomplete lines
        if chunk.len() < columns {
            let width = get_byte_width(format_char);
            for _ in chunk.len()..columns {
                for _ in 0..width {
                    write!(stdout, " ")?;
                }
            }
        }

        // Print ASCII representation
        write!(stdout, " ")?;
        for byte in chunk {
            let ch = if *byte >= 32 && *byte <= 126 {
                *byte as char
            } else {
                '.'
            };
            if use_color {
                write!(stdout, "{}", colorize_cyan(&ch.to_string()))?;
            } else {
                write!(stdout, "{}", ch)?;
            }
        }

        writeln!(stdout)?;
        offset = end;
    }
    Ok(())
}

fn get_byte_width(format_char: char) -> usize {
    match format_char {
        'x' => 4,  // "0x00" or "00"
        'X' => 4,
        'o' => 6,  // "0o0000" or "0000"
        'b' => 10, // "0b00000000" or "00000000"
        _ => 4,
    }
}

fn write_byte<W: Write>(w: &mut W, byte: u8, format_char: char, use_color: bool, prefix_enabled: bool) -> io::Result<()> {
    let formatted = match format_char {
        'x' => {
            if prefix_enabled {
                format!("0x{:02x}", byte)
            } else {
                format!("{:02x}", byte)
            }
        }
        'X' => {
