    println!("  -p, --places <func_places>  Set function wave output decimal places");
    println!("  -r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]");
    println!("  -h, --help                  Print help");
    println!("  -V, --version               Print version");
}

fn colorize_yellow(text: &str) -> String {
    format!("\x1b[33m{}\x1b[0m", text)
}

fn colorize_cyan(text: &str) -> String {
    format!("\x1b[36m{}\x1b[0m", text)
}

fn main() {
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    if args.help {
        print_help();
        return;
    }

    if args.version {
        println!("hx 0.7.0");
        return;
    }

    // Determine if colors should be used
    let use_color = if let Some(c) = args.color {
        c == 1
    } else {
        // Check NO_COLOR environment variable
        env::var("NO_COLOR").is_err()
    };

    // Default values
    let columns = args.cols.unwrap_or(10);
    let max_len = args.len;
    let format_char = args.format.unwrap_or('x');
    let prefix_enabled = args.prefix.unwrap_or(1) == 1;

    // Read input
    let mut input = Vec::new();
    if let Some(path) = &args.inputfile {
        match File::open(path) {
            Ok(mut file) => {
                if let Err(_) = file.read_to_end(&mut input) {
                    eprintln!("Error reading file");
                    std::process::exit(1);
                }
            }
            Err(e) => {
                eprintln!("error: {} (os error {})", e, e.raw_os_error().unwrap_or(0));
                std::process::exit(1);
            }
        }
    } else {
        if let Err(_) = io::stdin().read_to_end(&mut input) {
            eprintln!("Error reading stdin");
            std::process::exit(1);
        }
    }

    // Limit by len if specified
    if let Some(max) = max_len {
        input.truncate(max);
    }

    // Process based on mode
    if let Some(array_format) = args.array {
        if let Err(_) = print_array_format(&input, array_format, use_color) {
            std::process::exit(1);
        }
    } else {
        if let Err(_) = print_hex_dump(&input, columns, format_char, use_color, prefix_enabled) {
            std::process::exit(0);  // Broken pipe is ok
        }
        let _ = writeln!(io::stdout().lock(), "   bytes: {}", input.len());
    }
}

fn print_hex_dump(input: &[u8], columns: usize, format_char: char, use_color: bool, prefix_enabled: bool) -> io::Result<()> {
    let mut stdout = io::stdout().lock();
    let mut offset = 0;
    while offset < input.len() {
        let end = std::cmp::min(offset + columns, input.len());
        let chunk = &input[offset..end];

        // Print offset
        write!(stdout, "0x{:06x}:", offset)?;

        // Print hex values
        write!(stdout, " ")?;
        for (i, byte) in chunk.iter().enumerate() {
            if i > 0 {
                write!(stdout, " ")?;
            }
            write_byte(&mut stdout, *byte, format_char, use_color, prefix_enabled)?;
        }

        // Padding for incomplete lines
        if chunk.len() < columns {
            let width = get_byte_width(format_char);
            for _ in chunk.len()..columns {
                for _ in 0..width {
                    write!(stdout, " ")?;
                }
            }
        }

        // Print ASCII representation
        write!(stdout, " ")?;
        for byte in chunk {
            let ch = if *byte >= 32 && *byte <= 126 {
                *byte as char
            } else {
                '.'
            };
            if use_color {
                write!(stdout, "{}", colorize_cyan(&ch.to_string()))?;
            } else {
                write!(stdout, "{}", ch)?;
            }
        }

        writeln!(stdout)?;
        offset = end;
    }
    Ok(())
}

fn get_byte_width(format_char: char) -> usize {
    match format_char {
        'x' => 4,  // "0x00" or "00"
        'X' => 4,
        'o' => 6,  // "0o0000" or "0000"
        'b' => 10, // "0b00000000" or "00000000"
        _ => 4,
    }
}

fn write_byte<W: Write>(w: &mut W, byte: u8, format_char: char, use_color: bool, prefix_enabled: bool) -> io::Result<()> {
    let formatted = match format_char {
        'x' => {
            if prefix_enabled {
                format!("0x{:02x}", byte)
            } else {
                format!("{:02x}", byte)
            }
        }
        'X' => {
            if prefix_enabled {
                format!("0x{:02X}", byte)
            } else {
                format!("{:02X}", byte)
            }
        }
        'o' => {
            if prefix_enabled {
                format!("0o{:04o}", byte)
            } else {
                format!("{:04o}", byte)
            }
        }
        'b' => {
            if prefix_enabled {
                format!("0b{:08b}", byte)
            } else {
                format!("{:08b}", byte)
            }
        }
        _ => format!("0x{:02x}", byte),
    };

    if use_color {
        write!(w, "{}", colorize_yellow(&formatted))
    } else {
        write!(w, "{}", formatted)
    }
}

fn print_array_format(input: &[u8], format: char, _use_color: bool) -> Result<(), Box<dyn std::error::Error>> {
    match format {
        'r' => {
            print_rust_array(input);
            Ok(())
        }
        'c' => {
            print_c_array(input);
            Ok(())
        }
        'g' => {
            print_go_array(input);
            Ok(())
        }
        'p' => {
            print_python_array(input);
            Ok(())
        }
        'k' => {
            print_kotlin_array(input);
            Ok(())
        }
        'j' => {
            print_java_array(input);
            Ok(())
        }
        's' => {
            print_swift_array(input);
            Ok(())
        }
        'f' => {
            print_fsharp_array(input);
            Ok(())
        }
        _ => Err(format!("Unknown array format: {}", format).into()),
    }
}

fn print_rust_array(input: &[u8]) {
    println!("let ARRAY: [u8; {}] = [", input.len());
    for (i, byte) in input.iter().enumerate() {
        if i % 10 == 0 {
            print!("    ");
        } else {
            print!(" ");
        }
        print!("0x{:02x},", byte);
        if (i + 1) % 10 == 0 {
            println!();
        }
    }
    if input.len() % 10 != 0 {
        println!();
    }
    println!("];");
}

